import pandas as pd
import numpy as np
import json
import matplotlib.pyplot as plt
import seaborn as sns
from datetime import datetime
import base64
from io import BytesIO

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Calculate KPIs
avg_hsc = df['HSC_Result'].mean()
excellent_rate = (df['HSC_Result'] >= 4.5).mean() * 100
at_risk_rate = (df['HSC_Result'] < 3.0).mean() * 100
gpa_delta = (df['HSC_Result'] - df['Previous_GPA']).mean()
attendance_corr = df['Attendance'].corr(df['HSC_Result'])

# Visualizations
plt.style.use('seaborn-v0_8-whitegrid')
charts = {}

# 1. Performance Distribution
fig, ax = plt.subplots(figsize=(8, 5))
sns.histplot(df['HSC_Result'], bins=20, kde=True, ax=ax, color='#3498db')
ax.set_title('Distribution of HSC Results')
ax.set_xlabel('HSC GPA')
ax.set_ylabel('Number of Students')
charts['hsc_dist'] = fig_to_base64(fig)
plt.close(fig)

# 2. District Performance
district_perf = df.groupby('District')['HSC_Result'].mean().sort_values()
fig, ax = plt.subplots(figsize=(10, 6))
district_perf.plot(kind='barh', ax=ax, color='#2ecc71')
ax.set_title('Average HSC Result by District')
ax.set_xlabel('Average HSC GPA')
ax.set_xlim(3.5, 4.5)
charts['district_perf'] = fig_to_base64(fig)
plt.close(fig)

# 3. Income vs Performance
df['Income_Group'] = pd.qcut(df['Family_Income_BDT'], 5, labels=['Lowest', 'Low', 'Middle', 'High', 'Highest'])
fig, ax = plt.subplots(figsize=(8, 5))
sns.boxplot(x='Income_Group', y='HSC_Result', data=df, ax=ax, palette='Blues')
ax.set_title('HSC Result by Family Income Quintile')
ax.set_xlabel('Income Quintile')
charts['income_perf'] = fig_to_base64(fig)
plt.close(fig)

# 4. Internet & Tuition Impact
fig, ax = plt.subplots(1, 2, figsize=(12, 5))
sns.barplot(x='Internet_Access', y='HSC_Result', data=df, ax=ax[0], palette='Set2')
ax[0].set_title('Impact of Internet Access')
ax[0].set_ylim(3.5, 4.5)
sns.barplot(x='Private_Tuition', y='HSC_Result', data=df, ax=ax[1], palette='Set2')
ax[1].set_title('Impact of Private Tuition')
ax[1].set_ylim(3.5, 4.5)
charts['internet_tuition'] = fig_to_base64(fig)
plt.close(fig)

# 5. Parent Education
fig, ax = plt.subplots(figsize=(8, 5))
order = ['Primary', 'Secondary', 'Higher Secondary', 'Graduate']
sns.barplot(x='Parent_Education', y='HSC_Result', data=df, order=order, ax=ax, palette='viridis')
ax.set_title('HSC Result by Parent Education Level')
ax.set_ylim(3.5, 4.5)
charts['parent_edu'] = fig_to_base64(fig)
plt.close(fig)

